            /
            <span class="cursor-pointer">{{ product.categories[0] }}</span>
            / {{ product.name }}
          </div>
          <div class="text-[#025048] mb-4">
            <div class="text-lg md:text-xl mb-4 cursor-pointer uppercase">
              {{ product.categories.join(', ') }}
