              </div>
              <div class="text-md md:text-xl mt-5">
                <input type="checkbox" /> Save my name, email, and website in
                this browser for the next time I comment.
              </div>
            </div>
            <button
              class="text-[#025048] hover:bg-[#025048] hover:text-white border-2 uppercase px-4 py-2 mt-5 text-xl"
            >
              Submit
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { useRoute, useRouter } from 'vue-router'
import { onMounted, ref, computed } from 'vue'
import productData from '@/data/products.json'
import { cartStore } from '@/stores/app'
import ZoomingCarousel from '@/components/ZoomingCarousel.vue'
import 'vue3-carousel/dist/carousel.css'

const product = ref(null)
const showDescription = ref(true)
const router = useRouter()
const cartItems = computed(() => cartStore().cart)

onMounted(() => {
  const route = useRoute()
  const productId = Number(route.params.id)
  product.value = productData.find(product => product.id === productId)
})

function ifAtleastOneItem() {
  return cartItems.value.findIndex(item => product.value.id === item.id)
}

function addProductToCart() {
  cartStore().addToCart(product.value)
}

function noOfProductInCart() {
  let count = 0
  cartItems.value.forEach(item =>
    item.id === product.value.id ? count++ : null,
  )
  return count
}
function removeProductFromCart() {
  const cartCopy = [...cartItems.value]
  const itemIndex = cartCopy.findIndex(item => item.id === product.value.id)
  cartCopy.splice(itemIndex, 1)
  cartStore().updateCart(cartCopy)
}
</script>

